// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }

    function testFuzz_property(address newOwner) public {
        c.initialize(); // owner becomes address(this), the caller of the boundary calls

        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: transferOwnership succeeds iff newOwner != address(0);
        // transferring to the zero address must revert (renounceOwnership is the only path).
        assertTrue(ok == (newOwner != address(0)), "transferOwnership(0) must revert and nonzero transfers must succeed");
    }
}
